private Position decodeOld(DeviceSession deviceSession, ChannelBuffer buf, int type, int index) {

    Position position = new Position();
    position.setDeviceId(deviceSession.getDeviceId());
    position.setProtocol(getProtocolName());

    position.set(Position.KEY_INDEX, index);

    // Check that we have enough bytes to read the time
    if (buf.readableBytes() >= 4) {
        position.setTime(new Date(buf.readUnsignedInt() * 1000));
    }

    // Check that we have enough bytes to read latitude and longitude
    if (buf.readableBytes() >= 8) {
        position.setLatitude(buf.readInt() / 1800000.0);
        position.setLongitude(buf.readInt() / 1800000.0);
    }

    // Check that we have enough bytes to read speed
    if (buf.readableBytes() >= 1) {
        position.setSpeed(UnitsConverter.knotsFromKph(buf.readUnsignedByte()));
    }

    // Check that we have enough bytes to read course
    if (buf.readableBytes() >= 2) {
        position.setCourse(buf.readUnsignedShort());
    }

    // Check that we have enough bytes to read network information
    if (buf.readableBytes() >= 9) { // 2 + 2 + 2 + 3 bytes for network
        position.setNetwork(new Network(CellTower.from(
                buf.readUnsignedShort(), buf.readUnsignedShort(), buf.readUnsignedShort(), buf.readUnsignedMedium())));
    }

    // Check that we have enough bytes to determine if the position is valid
    if (buf.readableBytes() >= 1) {
        position.setValid((buf.readUnsignedByte() & 0x01) != 0);
    }

    if (type == MSG_GPS) {

        if (buf.readableBytes() >= 2) {
            decodeStatus(position, buf.readUnsignedShort());
        }

        if (buf.readableBytes() >= 2 * 4) { // 4 * 2 bytes for additional data

            position.set(Position.KEY_BATTERY, buf.readUnsignedShort() * 0.001);

            position.set(Position.KEY_RSSI, buf.readUnsignedShort());

            position.set(Position.PREFIX_ADC + 1, buf.readUnsignedShort());
            position.set(Position.PREFIX_ADC + 2, buf.readUnsignedShort());

        }

    } else if (type == MSG_ALARM) {

        if (buf.readableBytes() >= 1) {
            position.set(Position.KEY_ALARM, decodeAlarm(buf.readUnsignedByte()));
        }

    } else if (type == MSG_STATE) {

        if (buf.readableBytes() >= 1) {
            int statusType = buf.readUnsignedByte();
            position.set(Position.KEY_EVENT, statusType);

            if (statusType == 0x01 || statusType == 0x02 || statusType == 0x03) {
                if (buf.readableBytes() >= 6) { // 4 + 2 bytes for time and status
                    buf.readUnsignedInt(); // device time
                    decodeStatus(position, buf.readUnsignedShort());
                }
            }
        }

    }

    return position;
}

